#table {
   font-family: Arial, Helvetica, sans-serif;
   border-collapse: collapse;
   width: 100%;
    
}

#table td, #table th {
  border: 1px solid #bfbdbd;
  padding: 2px;
  padding-top: 2px;
  padding-bottom: 2px;
}

#table tr:nth-child(even){background-color: #f2f2f2;}

#table tr:hover {background-color: #ddd;}

#head td {
  padding-top: 2px;
  padding-bottom: 2px;
  text-align: left;
  background-color: #4c85a6;
  color: white;
}


#main {
   margin-left: 20px;
   margin-right: 20px;
}
@media all {
   div .printedby {
       position: fixed;
       bottom: 0;
       text-align: center;
       font-size: xx-small;
       width: 100% !important;
   }
}
